Previous Rust program:
```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

fn main() {
    let m = Arc::new(Mutex::new(false));
    let cv = Arc::new(Condvar::new());

    let waiter_m = Arc::clone(&m);
    let waiter_cv = Arc::clone(&cv);
    let waiter = thread::spawn(move || {
        let mut guard = waiter_m.lock().unwrap();
        while *guard == false {
            guard = waiter_cv.wait(guard).unwrap();
        }
        drop(guard);
    });

    let notifier_m = Arc::clone(&m);
    let notifier_cv = Arc::clone(&cv);
    let notifier = thread::spawn(move || {
        let mut guard = notifier_m.lock().unwrap();
        *guard = true;
        notifier_cv.notify_one();
        drop(guard);
    });

    waiter.join().unwrap();
    notifier.join().unwrap();

    println!("DONE ready=true");
}
```

Feedback on that Rust program:
Spawned workers notifier#531, waiter#238 have no unambiguous named entry. Implement each CIR worker as a named Rust function with the same name and call it from its spawn closure. Preserve the verified CIR synchronization, resource names, and shared-state updates. Do not guess thread identity from spawn order.
Fix the Rust; do not change the design.

